package cue

import (
	_ "embed"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strings"

	"cuelang.org/go/cue"
	"cuelang.org/go/cue/cuecontext"
	cueerror "cuelang.org/go/cue/errors"
	"cuelang.org/go/encoding/yaml"
)

const (
	jsonFormat = "json"
	textFormat = "text"
)

var (
	//go:embed flipt.cue
	cueFile             []byte
	ErrValidationFailed = errors.New("validation failed")
)

// Result contains all validation errors found in a feature file.
type Result struct {
	Errors []Error `json:"errors"`
}

// FeaturesValidator holds the CUE context and compiled feature schema.
type FeaturesValidator struct {
	cue *cue.Context
	v   cue.Value
}

// NewFeaturesValidator compiles the embedded feature schema.
func NewFeaturesValidator() (*FeaturesValidator, error) {
	cctx := cuecontext.New()
	v := cctx.CompileBytes(cueFile)
	if err := v.Err(); err != nil {
		return nil, err
	}

	return &FeaturesValidator{cue: cctx, v: v}, nil
}

// Validate checks YAML content and returns every validation failure with its
// field path and source location.
func (v *FeaturesValidator) Validate(file string, b []byte) (Result, error) {
	f, err := yaml.Extract(file, b)
	if err != nil {
		return Result{Errors: validationErrors(file, err)}, ErrValidationFailed
	}

	yv := v.cue.BuildFile(f, cue.Scope(v.v))
	err = v.v.Unify(yv).Validate()
	if err != nil {
		return Result{Errors: validationErrors(file, err)}, ErrValidationFailed
	}

	return Result{Errors: []Error{}}, nil
}

// ValidateBytes takes a slice of bytes, and validates them against a cue definition.
func ValidateBytes(b []byte) error {
	cctx := cuecontext.New()

	return validate(b, cctx)
}

func validate(b []byte, cctx *cue.Context) error {
	v := cctx.CompileBytes(cueFile)

	f, err := yaml.Extract("", b)
	if err != nil {
		return err
	}

	yv := cctx.BuildFile(f, cue.Scope(v))
	yv = v.Unify(yv)

	return yv.Validate()
}

// Location contains information about where an error has occurred during cue
// validation.
type Location struct {
	File   string `json:"file,omitempty"`
	Line   int    `json:"line"`
	Column int    `json:"column"`
}

// Error is a collection of fields that represent positions in files where the user
// has made some kind of error.
type Error struct {
	Path     string   `json:"path,omitempty"`
	Message  string   `json:"message"`
	Location Location `json:"location"`
}

func validationErrors(file string, err error) []Error {
	ce := cueerror.Errors(err)
	if len(ce) == 0 {
		return []Error{{
			Message:  err.Error(),
			Location: Location{File: file},
		}}
	}

	result := make([]Error, 0, len(ce))
	for _, m := range ce {
		pathParts := m.Path()
		path := strings.Join(pathParts, ".")
		format, args := m.Msg()
		message := fmt.Sprintf(format, args...)
		if message == "field not allowed" && len(pathParts) > 0 {
			message = fmt.Sprintf("field %q is not allowed", pathParts[len(pathParts)-1])
		}

		location := Location{File: file}
		for _, pos := range m.InputPositions() {
			if sameFile(file, pos.Filename()) {
				location.Line = pos.Line()
				location.Column = pos.Column()
				break
			}
		}

		result = append(result, Error{
			Path:     path,
			Message:  message,
			Location: location,
		})
	}

	return result
}

func sameFile(input, position string) bool {
	if input == position {
		return true
	}
	if input == "" || position == "" {
		return false
	}

	inputAbs, inputErr := filepath.Abs(input)
	positionAbs, positionErr := filepath.Abs(position)
	return inputErr == nil && positionErr == nil && filepath.Clean(inputAbs) == filepath.Clean(positionAbs)
}

func writeErrorDetails(format string, result Result, w io.Writer) error {
	var sb strings.Builder

	buildErrorMessage := func() {
		sb.WriteString("❌ Validation failure!\n\n")

		for _, validationError := range result.Errors {
			fmt.Fprintf(&sb, "- File: %s\n  Line: %d, Column: %d\n", validationError.Location.File, validationError.Location.Line, validationError.Location.Column)
			if validationError.Path != "" {
				fmt.Fprintf(&sb, "  Field: %s\n", validationError.Path)
			}
			fmt.Fprintf(&sb, "  Message: %s\n\n", validationError.Message)
		}
	}

	switch format {
	case jsonFormat:
		return json.NewEncoder(w).Encode(result)
	case textFormat:
		buildErrorMessage()
	default:
		sb.WriteString("Invalid format chosen, defaulting to \"text\" format...\n")
		buildErrorMessage()
	}

	fmt.Fprint(w, sb.String())

	return nil
}

// ValidateFiles takes a slice of strings as filenames and validates them against
// our cue definition of features.
func ValidateFiles(dst io.Writer, files []string, format string) error {
	validator, err := NewFeaturesValidator()
	if err != nil {
		return err
	}

	result := Result{Errors: make([]Error, 0)}

	for _, f := range files {
		b, err := os.ReadFile(f)
		if err != nil {
			result.Errors = append(result.Errors, Error{
				Message:  fmt.Sprintf("failed to read file: %v", err),
				Location: Location{File: f},
			})
			continue
		}
		fileResult, err := validator.Validate(f, b)
		if errors.Is(err, ErrValidationFailed) {
			result.Errors = append(result.Errors, fileResult.Errors...)
		} else if err != nil {
			return err
		}
	}

	if len(result.Errors) > 0 {
		if err := writeErrorDetails(format, result, dst); err != nil {
			return err
		}

		return ErrValidationFailed
	}

	// For json format upon success, return no output to the user
	if format == jsonFormat {
		return nil
	}

	if format != textFormat {
		fmt.Fprint(dst, "Invalid format chosen, defaulting to \"text\" format...\n")
	}

	fmt.Fprintln(dst, "✅ Validation success!")

	return nil
}
